% 确保图例在饼图右侧且不遮挡数据。
% 重新绘制一个更可控的饼图版本：

\begin{scope}[shift={(0,0)}]
\pie[
    radius=2.5,
    text=pin, % 标签在扇区内部或附近
    style={fill=none, draw=black},
    text width=2cm
]
{
    55.3/煤炭,
    18.7/石油,
    8.9/天然气,
    17.1/非化石能源
};

% 手动添加图例到右侧
